package com.shopsphere.controller;
import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.sql.*;import java.math.BigDecimal;import java.util.*;import com.shopsphere.dao.ProductDAO;import com.shopsphere.util.DB;
@WebServlet(urlPatterns={"/admin","/admin/products","/admin/orders","/admin/categories","/admin/users"})
public class AdminServlet extends HttpServlet {
 private final ProductDAO products=new ProductDAO();private int num(String x,int def){try{return Integer.parseInt(x);}catch(Exception e){return def;}}
 @Override protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException {try {String path=r.getServletPath();r.setAttribute("products",products.all());List<Map<String,Object>> orders=new ArrayList<>(),users=new ArrayList<>(),cats=new ArrayList<>();try(Connection c=DB.connect()) {for(String kind:List.of("orders","users","categories")){String sql=switch(kind){case "orders"->"SELECT o.order_id,u.name customer,o.total_amount,o.order_status,o.created_at FROM orders o JOIN users u ON u.user_id=o.user_id ORDER BY o.order_id DESC";case "users"->"SELECT user_id,name,email,role,status FROM users ORDER BY user_id DESC";default->"SELECT category_id,name,description FROM categories ORDER BY category_id DESC";};try(PreparedStatement st=c.prepareStatement(sql);ResultSet rs=st.executeQuery()){ResultSetMetaData md=rs.getMetaData();while(rs.next()){Map<String,Object> m=new HashMap<>();for(int i=1;i<=md.getColumnCount();i++)m.put(md.getColumnLabel(i),rs.getObject(i));switch(kind){case "orders"->orders.add(m);case "users"->users.add(m);default->cats.add(m);}}}}}
 r.setAttribute("orders",orders);r.setAttribute("customers",users);r.setAttribute("categories",cats);r.setAttribute("section",path.equals("/admin")?"dashboard":path.substring(path.lastIndexOf('/')+1));r.getRequestDispatcher("/WEB-INF/views/admin.jsp").forward(r,s);
 }catch(SQLException e){getServletContext().log("Admin error",e);s.sendError(500,"Database unavailable");}}
 @Override protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException {r.setCharacterEncoding("UTF-8");try {switch(r.getServletPath()){
 case "/admin/products"->{int id=num(r.getParameter("id"),0);if("delete".equals(r.getParameter("action")))products.hide(id);else {BigDecimal price=new BigDecimal(r.getParameter("price"));int stock=num(r.getParameter("stock"),-1);if(price.signum()<0||stock<0||r.getParameter("name").isBlank())throw new IllegalArgumentException("Invalid product fields");products.save(id,r.getParameter("name"),r.getParameter("brand"),num(r.getParameter("category"),1),r.getParameter("description"),price,stock,r.getParameter("image"));}}
 case "/admin/orders"->{String status=r.getParameter("status");if(!List.of("PLACED","PROCESSING","SHIPPED","DELIVERED","CANCELLED").contains(status))throw new IllegalArgumentException("Invalid status");try(Connection c=DB.connect();PreparedStatement ps=c.prepareStatement("UPDATE orders SET order_status=? WHERE order_id=?")){ps.setString(1,status);ps.setInt(2,num(r.getParameter("id"),-1));ps.executeUpdate();}}
 case "/admin/categories"->{try(Connection c=DB.connect();PreparedStatement ps=c.prepareStatement("INSERT INTO categories(name,description) VALUES(?,?)")){ps.setString(1,r.getParameter("name"));ps.setString(2,r.getParameter("description"));ps.executeUpdate();}}
 default -> {s.sendError(405);return;}}
 s.sendRedirect(r.getContextPath()+r.getServletPath());}catch(Exception e){getServletContext().log("Admin update failed",e);s.sendError(400,"Could not update: invalid input or database constraint");}}
}
